```java
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

/**
 * 二叉树层序遍历实现
 */
public class BinaryTreeLevelOrderTraversal {

    /**
     * 层序遍历算法
     * @param root 二叉树根节点
     * @return 按层级顺序排列的节点值列表
     */
    public List<List<Integer>> levelOrder(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();

        if (root == null) {
            return result;
        }

        // 使用LinkedList作为队列实现
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);  // 根节点入队

        while (!queue.isEmpty()) {
            int levelSize = queue.size();  // 当前层的节点数
            List<Integer> currentLevel = new ArrayList<>();

            // 遍历当前层的所有节点
            for (int i = 0; i < levelSize; i++) {
                TreeNode current = queue.poll();  // 出队
                currentLevel.add(current.val);    // 处理当前节点

                // 将左右子节点入队
                if (current.left != null) {
                    queue.offer(current.left);
                }
                if (current.right != null) {
                    queue.offer(current.right);
                }
            }

            result.add(currentLevel);  // 将当前层的结果添加到总结果
        }

        return result;
    }

    /**
     * 辅助方法：将结果转换为易读的字符串格式
     */
    public String resultToString(List<List<Integer>> result) {
        StringBuilder sb = new StringBuilder();
        sb.append("层序遍历结果:\n");

        for (int i = 0; i < result.size(); i++) {
            sb.append("第 ").append(i + 1).append(" 层: ");
            sb.append(result.get(i).toString());
            sb.append("\n");
        }

        return sb.toString();
    }
}
```

