import java.util.LinkedList;
import java.util.Queue;

public class ShortestPath {
    private int V; // 顶点数
    private LinkedList<Integer>[] adj; // 邻接表

    public ShortestPath(int v) {
        V = v;
        if (v <= 0) {
            throw new IllegalArgumentException("顶点数必须大于0");
        }
        adj = new LinkedList[v];
        for (int i = 0; i < v; ++i) {
            adj[i] = new LinkedList<>();
        }
    }

    public void addEdge(int v, int w) {
        // 检查顶点是否有效
        if (v < 0 || v >= V || w < 0 || w >= V) {
            throw new IllegalArgumentException("无效的顶点索引");
        }
        adj[v].add(w);
    }

    public void bfs(int s) {
        // 检查起点是否有效
        if (s < 0 || s >= V) {
            throw new IllegalArgumentException("起点索引无效");
        }

        boolean[] visited = new boolean[V];
        int[] distance = new int[V];
        int[] parent = new int[V];

        // 初始化数组
        for (int i = 0; i < V; i++) {
            visited[i] = false;
            distance[i] = -1; // 未访问
            parent[i] = -1;
        }

        Queue<Integer> queue = new LinkedList<>();
        visited[s] = true;
        distance[s] = 0;
        queue.add(s);

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    distance[v] = distance[u] + 1;
                    parent[v] = u;
                    queue.add(v);
                }
            }
        }

        // 打印结果
        System.out.println("BFS 从节点 " + s + " 开始：");
        for (int i = 0; i < V; i++) {
            if (distance[i] != -1) {
                System.out.println("到节点 " + i + " 的距离: " + distance[i]);
                System.out.println("路径: " + getPath(parent, s, i));
            } else {
                System.out.println("节点 " + i + " 无法到达");
            }
        }
    }

    private String getPath(int[] parent, int start, int end) {
        if (end == -1 || end == start) {
            return start + "";
        }
        StringBuilder path = new StringBuilder();
        int current = end;
        while (current != start) {
            path.insert(0, current + " -> ");
            current = parent[current];
            if (current == -1) {
                return "无路径"; // 处理未连通情况
            }
        }
        path.insert(0, start);
        return path.toString();
    }

