    skipList.insert(6);
    skipList.insert(2);
    skipList.insert(1);
    skipList.insert(5);

    cout << "反转前:" << endl;
    skipList.display();

    skipList.reverse();

    cout << "反转后:" << endl;
    skipList.display();

    // 测试用例2: 空跳表反转
    cout << "=== 测试用例2: 空跳表反转 ===" << endl;
    SkipList<int> emptyList;
    cout << "空跳表反转前:" << endl;
    emptyList.display();
    emptyList.reverse();
    cout << "空跳表反转后:" << endl;
    emptyList.display();

    // 测试用例3: 单节点跳表反转
    cout << "=== 测试用例3: 单节点跳表反转 ===" << endl;
    SkipList<int> singleList;
    singleList.insert(10);
    cout << "单节点反转前:" << endl;
    singleList.display();
    singleList.reverse();
    cout << "单节点反转后:" << endl;
    singleList.display();

    // 测试用例4: 搜索验证
    cout << "=== 测试用例4: 搜索验证 ===" << endl;
    SkipList<int> searchList;
    searchList.insert(10);
    searchList.insert(20);
    searchList.insert(30);
    cout << "搜索20: " << (searchList.search(20) ? "找到" : "未找到") << endl;
    searchList.reverse();
    cout << "反转后搜索20: " << (searchList.search(20) ? "找到" : "未找到") << endl;

    return 0;
}
```

