### JavaScript 代码
```javascript
// 红黑树节点类
class Node {
    constructor(value) {
        this.value = value;
        this.color = 'red'; // 新节点初始为红色
        this.left = null;
        this.right = null;
        this.parent = null;
    }
}

// 红黑树类
class RedBlackTree {
    constructor() {
        // 定义 NIL 节点（代表空叶子），始终为黑色
        this.NIL = new Node(null);
        this.NIL.color = 'black';
        this.root = this.NIL;
    }

    // 左旋转操作
    leftRotate(x) {
        let y = x.right;
        x.right = y.left;
        if (y.left !== this.NIL) {
            y.left.parent = x;
        }
        y.parent = x.parent;
        if (x.parent === this.NIL) {
            this.root = y;
        } else if (x === x.parent.left) {
            x.parent.left = y;
        } else {
            x.parent.right = y;
        }
        y.left = x;
        x.parent = y;
    }

    // 右旋转操作
    rightRotate(y) {
        let x = y.left;
        y.left = x.right;
        if (x.right !== this.NIL) {
            x.right.parent = y;
        }
        x.parent = y.parent;
        if (y.parent === this.NIL) {
            this.root = x;
        } else if (y === y.parent.right) {
            y.parent.right = x;
        } else {
            y.parent.left = x;
        }
        x.right = y;
        y.parent = x;
    }

    // 插入操作
    insert(value) {
        let newNode = new Node(value);
        newNode.left = this.NIL;
        newNode.right = this.NIL;

        let parent = this.NIL;
        let current = this.root;

        // 找到插入位置
        while (current !== this.NIL) {
            parent = current;
            if (newNode.value < current.value) {
                current = current.left;
            } else {
                current = current.right;
            }
        }

        newNode.parent = parent;
        if (parent === this.NIL) {
            this.root = newNode; // 插入根节点
        } else if (newNode.value < parent.value) {
            parent.left = newNode;
        } else {
            parent.right = newNode;
        }

        // 修复红黑树性质
        this.insertFixup(newNode);
    }

    // 插入后修复红黑树性质
    insertFixup(z) {
        while (z.parent.color === 'red') {
            if (z.parent === z.parent.parent.left) {
                let y = z.parent.parent.right; // 叔节点
                if (y.color === 'red') {
