                    z.parent.color = 'black';
                    y.color = 'black';
                    z.parent.parent.color = 'red';
                    z = z.parent.parent;
                } else {
                    // 情况2：叔节点为黑色，且 z 是右子节点
                    if (z === z.parent.right) {
                        z = z.parent;
                        this.leftRotate(z);
                    }
                    // 情况3：叔节点为黑色，且 z 是左子节点
                    z.parent.color = 'black';
                    z.parent.parent.color = 'red';
                    this.rightRotate(z.parent.parent);
                }
            } else {
                let y = z.parent.parent.left; // 叔节点
                if (y.color === 'red') {
                    // 情况1：叔节点为红色，重新着色
                    z.parent.color = 'black';
                    y.color = 'black';
                    z.parent.parent.color = 'red';
                    z = z.parent.parent;
                } else {
                    // 情况2：叔节点为黑色，且 z 是左子节点
                    if (z === z.parent.left) {
                        z = z.parent;
                        this.rightRotate(z);
                    }
                    // 情况3：叔节点为黑色，且 z 是右子节点
                    z.parent.color = 'black';
                    z.parent.parent.color = 'red';
                    this.leftRotate(z.parent.parent);
                }
            }
        }
        this.root.color = 'black'; // 确保根节点为黑色
    }

    // 中序遍历，返回有序数组
    inOrderTraversal(node = this.root) {
        let result = [];
        if (node !== this.NIL) {
            result = result.concat(this.inOrderTraversal(node.left));
            result.push(node.value);
            result = result.concat(this.inOrderTraversal(node.right));
        }
        return result;
    }
}

// 合并两个有序数组的函数
function mergeSortedArrays(arr1, arr2) {
    const tree = new RedBlackTree();
    // 插入第一个数组的所有元素
