    public ListNode reverseList() {
        // 边界条件：空链表或单节点链表
        if (head == null || head.next == null) {
            return head;
        }

        // 首先，检测链表是否有环
        int size = 0;
        ListNode current = head;
        while (current != null) {
            size++;
            current = current.next;
        }

        UnionFind uf = new UnionFind(size);
        current = head;
        int index = 0;
        boolean hasCycle = false;
        while (current != null) {
            if (index > 0) { // 从第二个节点开始检查
                ListNode temp = head;
                int tempIndex = 0;
                while (temp != current) {
                    if (uf.isConnected(index, tempIndex)) {
                        hasCycle = true;
                        break;
                    }
                    temp = temp.next;
                    tempIndex++;
                }
            }
            if (hasCycle) {
                break;
            }
            current = current.next;
            index++;
        }

        if (hasCycle) {
            System.out.println("链表存在环，无法反转。");
            return null;
        }

        // 使用迭代方法反转链表
        ListNode prev = null;
        ListNode next = null;
        current = head;
        while (current != null) {
            next = current.next;
            current.next = prev;
            prev = current;
            current = next;
        }
        head = prev;
        return head;
    }

