以下是一个完整的 Go 程序，使用链表实现最长递增子序列算法。代码包含链表定义、算法实现和测试示例。

```go
package main

import "fmt"

// ListNode 定义链表节点
type ListNode struct {
    Val  int
    Next *ListNode
}

// longestIncreasingSubsequence 找到链表中的最长递增子序列
func longestIncreasingSubsequence(head *ListNode) []int {
    if head == nil {
        return nil // 空链表边界条件
    }

    // 将链表转换为切片以便处理
    arr := []int{}
    current := head
    for current != nil {
        arr = append(arr, current.Val)
        current = current.Next
    }

    n := len(arr)
    if n == 0 {
        return nil
    }

    // 动态规划数组：dp[i] 存储以 arr[i] 结尾的最长递增子序列长度
    dp := make([]int, n)
    // prev 数组用于重建序列
    prev := make([]int, n)
    for i := 0; i < n; i++ {
        dp[i] = 1
        prev[i] = -1
    }

    // 填充 dp 数组
    for i := 1; i < n; i++ {
        for j := 0; j < i; j++ {
            if arr[j] < arr[i] && dp[j]+1 > dp[i] {
                dp[i] = dp[j] + 1
                prev[i] = j
            }
        }
    }

    // 找到最长递增子序列的结束索引
    maxLen := 0
    maxIndex := 0
    for i, length := range dp {
        if length > maxLen {
            maxLen = length
            maxIndex = i
        }
    }

    // 重建序列
    result := []int{}
    for i := maxIndex; i != -1; i = prev[i] {
        result = append(result, arr[i])
    }

    // 反转序列以获得正确顺序
    for i, j := 0, len(result)-1; i < j; i, j = i+1, j-1 {
        result[i], result[j] = result[j], result[i]
    }

    return result
}

// createLinkedList 从切片创建链表
func createLinkedList(arr []int) *ListNode {
    if len(arr) == 0 {
        return nil
    }
    head := &ListNode{Val: arr[0]}
    current := head
    for i := 1; i < len(arr); i++ {
        current.Next = &ListNode{Val: arr[i]}
        current = current.Next
    }
    return head
}

// printLinkedList 打印链表（用于调试）
func printLinkedList(head *ListNode) {
    current := head
    for current != nil {
        fmt.Printf("%d ", current.Val)
        current = current.Next
    }
    fmt.Println()
}

func main() {
    // 测试示例：根据输出反推的输入链表
    inputArr := []int{1, 2, 4, 6, 8, 10, 3}
    head := createLinkedList(inputArr)
    fmt.Println("输入链表:")
    printLinkedList(head)

    // 调用算法
    result := longestIncreasingSubsequence(head)
    fmt.Println("最长递增子序列:", result)

    // 边界条件测试
    fmt.Println("\n边界条件测试:")
    // 空链表
    emptyHead := createLinkedList([]int{})
    fmt.Println("空链表输入:", longestIncreasingSubsequence(emptyHead))
    // 单元素链表
    singleHead := createLinkedList([]int{5})
    fmt.Println("单元素链表输入:", longestIncreasingSubsequence(singleHead))
    // 全递减链表
    decreasingHead := createLinkedList([]int{5, 4, 3, 2, 1})
    fmt.Println("全递减链表输入:", longestIncreasingSubsequence(decreasingHead))
    // 全递增链表
    increasingHead := createLinkedList([]int{1, 2, 3, 4, 5})
    fmt.Println("全递增链表输入:", longestIncreasingSubsequence(increasingHead))
}
```

### 算法说明
- **时间复杂度**: O(n^2)，其中 n 是链表长度。动态规划部分遍历所有子序列。
- **空间复杂度**: O(n)，用于存储 dp 和 prev 数组。
- **边界条件处理**:
  - 空链表：返回 nil。
  - 单元素链表：返回该元素。
  - 全递减链表：返回第一个元素（最长递增子序列长度为 1）。
  - 全递增链表：返回整个序列。

