## 示例：正确、完整的 BFS 最短路径实现（C++）

```cpp
#include <bits/stdc++.h>
using namespace std;

vector<int> bfs_shortest_path(const vector<vector<int>>& adj, int src, int target) {
    const int INF = INT_MAX;
    int n = adj.size();
    vector<int> dist(n, INF);
    vector<int> parent(n, -1);
    vector<bool> visited(n, false);

    queue<int> q;
    q.push(src);
    dist[src] = 0;
    visited[src] = true;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (u == target) break;               // 已经找到目标，可提前结束

        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q.push(v);
            }
        }
    }

    // 重建路径（如果需要）
    vector<int> path;
    if (dist[target] == INF) return {};       // 不可达
    for (int cur = target; cur != -1; cur = parent[cur])
        path.push_back(cur);
    reverse(path.begin(), path.end());
    return path;   // 返回最短路径节点序列
}

// 简单测试
int main() {
    int n = 6;
    vector<vector<int>> adj(n);
    // 构造无向图
    vector<pair<int,int>> edges = {{0,1},{0,2},{1,3},{2,3},{3,4},{4,5}};
    for (auto [u,v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<int> path = bfs_shortest_path(adj, 0, 5);
    if (path.empty()) {
        cout << "No path found.\n";
    } else {
        cout << "Shortest path: ";
        for (int v : path) cout << v << ' ';
        cout << "\n";
    }
    return 0;
}
```

**关键点说明**  

1. **入队时立即标记 `visited`**：防止节点在同一次 BFS 中被重复加入。  
2. **距离数组 `dist` 初始化为 `INF`**，起点设为 0。  
3. **保存 `parent`**，在找到目标后可回溯得到完整路径。  
4. **提前终止**：当 `u == target` 时即可退出外层循环（可选）。  
5. **处理不可达情况**：若 `dist[target]` 仍为 `INF`，返回空路径或 `-1`。  

