## 需求概述
- **目标**：在 **JavaScript** 项目里使用 **队列（Queue）** 实现 **最短路径**（Shortest Path）算法。  
- **时间复杂度**：要求整体运行时间在 **O(n log n)** 以内。  
- **实现思路**：在无权图（un‑weighted graph）中，最短路径可以用 **BFS（Breadth‑First Search）** 直接求得。BFS 正好使用 FIFO 队列，时间复杂度为 **O(|V|+|E|)**，在稀疏图（即 |E|≈|V|）时等于 **O(n)**，必然满足 O(n log n) 的限制。  

下面给出完整的实现代码、关键注释以及几组测试用例，帮助你直接拷贝到项目中使用。

---

## 1. 核心实现

### 1.1 简单的 FIFO 队列（可自行替换为社区的 `Queue` 实现）

```js
/**
 * 简易 FIFO 队列
 * 只提供最常用的 enqueue / dequeue / isEmpty 三个方法
 */
class Queue {
  constructor() {
    this._items = [];
  }

  enqueue(item) {
    this._items.push(item);
  }

  dequeue() {
    return this._items.shift();   // Array.shift 在 JS 引擎中已经做了优化
  }

  isEmpty() {
    return this._items.length === 0;
  }

  // 方便调试时可查看当前队列内容
  toArray() {
    return [...this._items];
  }
}
```

### 1.2 BFS 求单源最短路径（返回距离 map）

```js
/**
 * 使用 BFS（队列）求从 start 出发到所有可达节点的最短距离
 * @param {Object} graph   邻接表，键为节点标识，值为相邻节点数组
 * @param {any}    start   起始节点（可以是字符串、数字等任意可做键的类型）
 * @returns {Object}       { node: distance }，distance 为从 start 到 node 的最短边数
 */
function shortestDistancesBFS(graph, start) {
  const distances = {};      // 记录每个节点的最短距离
  const visited = new Set(); // 防止重复入队
  const q = new Queue();

  // 初始化
  visited.add(start);
  distances[start] = 0;
  q.enqueue(start);

  while (!q.isEmpty()) {
    const u = q.dequeue();          // 当前正在遍历的节点
    const neighbors = graph[u] || []; // 兼容图中出现孤立节点

    for (const v of neighbors) {
      if (!visited.has(v)) {
        visited.add(v);
        distances[v] = distances[u] + 1; // 边权为 1，故距离 +1
        q.enqueue(v);
      }
    }
  }

  return distances;
}
```

### 1.3 重建具体路径（可选）

如果你不仅想知道距离，还想得到 **具体的节点序列**，可以在 BFS 过程中额外记录“前驱”：

```js
/**
 * 返回从 start 到 end 的最短路径（节点数组），若不可达返回 null
 * @param {Object} graph   邻接表
 * @param {any}    start   起点
 * @param {any}    end     终点
 * @returns {Array|null}   路径数组或 null
 */
function shortestPathBFS(graph, start, end) {
  if (start === end) return [start];

  const visited = new Set();
  const prev = new Map();      // 记录每个节点的前驱
  const q = new Queue();

  visited.add(start);
  q.enqueue(start);

  while (!q.isEmpty()) {
    const u = q.dequeue();
    const neighbors = graph[u] || [];

    for (const v of neighbors) {
      if (!visited.has(v)) {
        visited.add(v);
        prev.set(v, u);        // 记录前驱
        if (v === end) {       // 已经找到终点，可以提前退出
          return reconstructPath(prev, start, end);
        }
        q.enqueue(v);
      }
    }
  }

  // 循环结束仍未到达 end，说明不可达
  return null;
}

/**
 * 根据前驱表逆向重建路径
 */
function reconstructPath(prev, start, end) {
  const path = [];
  let cur = end;
  while (cur !== undefined) {
    path.unshift(cur);
    cur = prev.get(cur);
  }
  // 再次确认起点是否匹配（防止异常）
  return path[0] === start ? path : null;
}
```

