    tail = dummy
    for v in arr:
        tail.next = ListNode(v)
        tail = tail.next
    return dummy.next

def print_list(head):
    vals = []
    while head:
        vals.append(str(head.val))
        head = head.next
    print(" -> ".join(vals) if vals else "Empty")

if __name__ == "__main__":
    for arr in [[], [1], [1,2], [1,2,3,4,5]]:
        head = build_list(arr)
        print("原链表:", end=" ")
        print_list(head)
        rev = reverse_list_by_bfs(head)
        print("反转后:", end=" ")
        print_list(rev)
        print("-" * 30)
