```java
import java.util.*;

/**
 * Trie（前缀树）实现
 * 只支持小写字母单词
 */
class Trie {
    /** Trie 结点 */
    private static class TrieNode {
        TrieNode[] children; // 26 个子结点
        boolean isEnd;       // 是否为某个单词的结束

        TrieNode() {
            children = new TrieNode[26];
            isEnd = false;
        }
    }

    private final TrieNode root;

    public Trie() {
        root = new TrieNode();
    }

    /** 插入单词 */
    public void insert(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                node.children[idx] = new TrieNode();
            }
            node = node.children[idx];
        }
        node.isEnd = true;
    }

    /** 查询单词是否存在于 Trie 中（必须是完整单词） */
    public boolean search(String word) {
        TrieNode node = searchNode(word);
        return node != null && node.isEnd;
    }

    private TrieNode searchNode(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                return null;
            }
            node = node.children[idx];
        }
        return node;
    }

    /**
     * 返回与给定单词只差一个字符、且存在于 Trie 中的所有单词（即邻居）。
     * 实现思路：对单词的每一位尝试替换为 'a'~'z'（除原字符），然后在 Trie 中查找。
     */
    public List<String> getNeighbors(String word) {
        List<String> neighbors = new ArrayList<>();
        char[] chars = word.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            char original = chars[i];
            for (char c = 'a'; c <= 'z'; c++) {
                if (c == original) continue; // 跳过相同字符
                chars[i] = c;
                String candidate = new String(chars);
                if (search(candidate)) {
                    neighbors.add(candidate);
                }
            }
            chars[i] = original; // 恢复原字符
        }
        return neighbors;
    }
}

/**
 * 单词梯（Word Ladder）求解器
 * 使用 BFS + Trie 找到从 start 到 end 的最短转换路径
 */
class WordLadder {
    /**
     * @param start 起始单词
     * @param end   目标单词
     * @param dict  词典（所有合法单词的集合）
     * @return 从 start 转换到 end 所需的最少步数（包含 start 与 end），
     *         若不存在转换路径返回 0
     */
    public int ladderLength(String start, String end, List<String> dict) {
        // 1. 把词典放进 Trie
        Trie trie = new Trie();
        for (String w : dict) {
            trie.insert(w);
        }

        // 2. BFS 初始化
        Queue<String> queue = new LinkedList<>();
        queue.offer(start);
        Set<String> visited = new HashSet<>();
        visited.add(start);

        // 3. BFS 主循环
        int depth = 1; // 已经包含了 start
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            for (int i = 0; i < levelSize; i++) {
                String cur = queue.poll();
                if (cur.equals(end)) {
                    return depth;
                }
                // 通过 Trie 获得所有合法邻居
                for (String neighbor : trie.getNeighbors(cur)) {
                    if (!visited.contains(neighbor)) {
                        visited.add(neighbor);
                        queue.offer(neighbor);
                    }
                }
            }
            depth++;
        }
        // 无法到达
        return 0;
    }
}

/**
