## 2. 完整代码（merge.go）

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// ---------- 1. Trie 定义 ----------
const (
	DigitCount = 10 // 10 位十进制（足够覆盖 int32 范围）
)

// TrieNode 表示前缀树的一个结点
type TrieNode struct {
	children [DigitCount]*TrieNode // 0‑9 十个分支
	cnt      int                   // 以该结点为结尾的数出现了多少次（叶子结点的计数）
}

// Trie 公开的前缀树结构
type Trie struct {
	root *TrieNode
}

// NewTrie 初始化一棵空 Trie
func NewTrie() *Trie {
	return &Trie{root: &TrieNode{}}
}

// ---------- 2. 辅助函数：整数 <-> 定长字符串 ----------
const (
	// 2^31，用于把有符号 int32 映射到无符号 uint32
	offset = uint32(1 << 31)
	// 每个数字固定 10 位十进制（0~9），加上可能的负号我们已经在映射阶段去掉了
	digitFmt = "%010d"
)

// toFixedString 把有符号 int 转换为定长、无符号、零填充的十进制字符串
func toFixedString(n int) string {
	// 先把有符号整数转为 uint32（加上偏移量），保证全部是非负数
	u := uint32(n) + offset
	return fmt.Sprintf(digitFmt, u)
}

// fromFixedString 把定长字符串还原为原始 int（只在最终输出时使用）
func fromFixedString(s string) int {
	u, _ := strconv.ParseUint(s, 10, 32)
	return int(u) - int(offset)
}

// ---------- 3. 插入 ----------
// Insert 将一个已排序的数组中的所有元素插入 Trie
// 注意：数组本身必须是升序的，插入顺序不影响最终结果
func (t *Trie) Insert(arr []int) {
	if len(arr) == 0 {
		return
	}
	node := t.root
	for _, v := range arr {
		fixed := toFixedString(v) // 统一成 10 位字符串
		for _, ch := range fixed {
			d := int(ch - '0')
			if node.children[d] == nil {
				node.children[d] = &TrieNode{}
			}
			node = node.children[d]
		}
		// 到达数字的末尾，计数 +1
		node.cnt++
	}
}

// ---------- 4. 归并（遍历） ----------
// InOrder 按递增顺序返回所有已经插入的整数
// 使用显式栈避免递归导致的栈溢出
func (t *Trie) InOrder() []int {
	var result []int
	// 栈中保存当前结点以及下一个要访问的数字索引（0‑9）
	type frame struct {
		node   *TrieNode
		digit  int // 下一个要遍历的子分支（0‑9）
	}
	stack := []frame{{node: t.root, digit: 0}}

	for len(stack) > 0 {
		// 取出栈顶帧
		lf := len(stack) - 1
		cur := stack[lf].node
		idx := stack[lf].digit

		if idx == 0 && cur.cnt > 0 {
			// 当前结点是一个数字的结束位置，输出 cnt 次
			for i := 0; i < cur.cnt; i++ {
				result = append(result, fromFixedString(buildPath(cur)))
			}
		}

		if idx < DigitCount {
			// 继续遍历子节点
			stack[lf].digit = idx + 1 // 下次再回到当前结点时，直接跳到下一个分支
			if child := cur.children[idx]; child != nil {
				// 把子结点压栈，下一次从 digit=0 开始
				stack = append(stack, frame{node: child, digit: 0})
			}
		} else {
			// 所有子分支都已遍历，弹出
			stack = stack[:lf]
		}
	}
	return result
}

// buildPath 递归回溯得到从根到当前叶子结点的数字字符串（仅供调试或小数据量使用）
// 为降低递归深度，这里使用简单的递归；因为路径长度固定为 10，递归栈非常浅
func buildPath(node *TrieNode) string {
	var sb strings.Builder
	var dfs func(*TrieNode)
	dfs = func(n *TrieNode) {
		for d := DigitCount - 1; d >= 0; d-- { // 从最高位到低位
			if n.children[d] != nil {
				sb.WriteByte('0' + byte(d))
				dfs(n.children[d])
				return
			}
		}
	}
	dfs(node)
	return sb.String()
}

// ---------- 5. 对外接口 ----------
// MergeSortedArrays 接受若干已排序的 int 切片，返回一个完整的有序切片
func MergeSortedArrays(arrays ...[]int) []int {
	trie := NewTrie()
	for _, arr := range arrays {
		trie.Insert(arr) // 插入过程已经保证了顺序无关性
	}
	return trie.InOrder()
}

// ---------- 6. 示例 + 简单测试 ----------
func main() {
	// 示例 1：基本合并
	arr1 := []int{1, 3, 5, 7}
	arr2 := []int{2, 4, 6, 8}
	arr3 := []int{0, 9, 10, 11}
	res := MergeSortedArrays(arr1, arr2, arr3)
