	// 示例 4：全部为空
	res4 := MergeSortedArrays([]int{}, []int{})
	fmt.Println("示例 4（全空）:", res4)

	// 示例 5：大规模数据（仅示例，实际使用请自行对拍性能）
	// 这里不打印，仅检测是否 panic
	big := make([]int, 1_000_000)
	for i := range big {
