		}
		// 解析一行整数（以空格或逗号分隔）
		fields := strings.FieldsFunc(line, func(r rune) bool {
			return r == ' ' || r == ','
		})
		arr := make([]int, 0, len(fields))
		for _, f := range fields {
			if v, err := strconv.Atoi(f); err == nil {
				arr = append(arr, v)
			}
		}
		arrays = append(arrays, arr)
	}
	if len(arrays) == 0 {
		fmt.Println("未输入任何数组")
		return
	}
	res := MergeSortedArrays(arrays...)
	fmt.Printf("合并结果：%v\n", res)
}
