use std::collections::HashSet;

fn two_sum_with_hash_and_sort(nums: &[i32], target: i32) -> Vec<i32> {
    // 1. 把数组元素放入 HashSet，便于 O(1) 查找
    let set: HashSet<i32> = nums.iter().cloned().collect();

    // 2. 遍历数组，找出所有可以配对成功的元素
    let mut result: Vec<i32> = Vec::new();
    for &x in nums {
        let complement = target - x;
        if set.contains(&complement) {
            result.push(x); // x 可以和某个元素（可能是自己）配对得到 target
        }
    }

    // 3. 对结果排序，满足 O(n log n) 要求
    result.sort();

    result
}

fn main() {
    let nums = vec![2, 4, 6, 8, 10];
    let target = 12;
    let ans = two_sum_with_hash_and_sort(&nums, target);
    println!("{:?}", ans); // 输出: [2, 4, 6, 8, 10]
}
```

