## 思路说明  

本题要求 **使用哈希表（Go 中的 `map`）** 来实现单链表的反转。  
常规的原地反转只需要三个指针（prev、cur、next），这里我们把“遍历一次，把节点保存到 map 中”当作哈希表的使用方式，然后再依据保存的节点重新连线完成反转。**实现步骤**  

1. **遍历链表**，把每个节点指针保存到 `map[int]*ListNode` 中，键是节点的顺序索引（从 0 开始），值是指向该节点的指针。遍历的同时得到链表长度 `len`。  
2. **重新连线**：从最后一个节点开始（索引 `len‑1`），让它的 `Next` 指向前一个节点（索引 `len‑2`），依此类推，直到索引 `1` 指向索引 `0`；最后把索引 `0` 的 `Next` 设为 `nil`。  
3. 返回map中索引为 `len‑1` 的节点，即为反转后的链表头。

该实现只使用了 Go 标准库（`fmt`、`testing`），没有引入第三方依赖。

---

## 完整代码

> 把下面的代码保存为 `reverse_linked_list.go`，即可直接运行演示或执行单元测试。

```go
package main

import (
	"fmt"
	"testing"
)

// ---------- 链表节点定义 ----------
type ListNode struct {
	Val  int
	Next *ListNode
}

// ---------- 使用哈希表反转链表 ----------
// ReverseListWithHash 用 map 保存节点顺序，再重新连线实现就地反转
func ReverseListWithHash(head *ListNode) *ListNode {
	if head == nil {
		return nil
	}

	// 1. 把节点按顺序存入 map
	nodeMap := make(map[int]*ListNode)
	cur := head
	idx := 0
	for cur != nil {
		nodeMap[idx] = cur
		idx++
		cur = cur.Next
	}
	length := idx

	// 只有一个节点或为空直接返回
	if length <= 1 {
		return head
	}

	// 2. 逆序重新设置 Next 指针
	for i := length - 1; i > 0; i-- {
		nodeMap[i].Next = nodeMap[i-1]
	}
	// 3. 头部节点的 Next 设为 nil
	nodeMap[0].Next = nil

	// 4. 新的头结点是原来的尾部
	return nodeMap[length-1]
}

// ---------- 辅助函数（演示 & 单元测试） ----------
func listToSlice(head *ListNode) []int {
	var sl []int
	for cur := head; cur != nil; cur = cur.Next {
		sl = append(sl, cur.Val)
	}
	return sl
}

func buildList(vals []int) *ListNode {
	if len(vals) == 0 {
		return nil
	}
	head := &ListNode{Val: vals[0]}
	cur := head
	for i := 1; i < len(vals); i++ {
		cur.Next = &ListNode{Val: vals[i]}
		cur = cur.Next
	}
	return head
}

// ---------- 单元测试 ----------
func TestReverseListWithHash(t *testing.T) {
	tests := []struct {
		name     string
		input    []int
		expected []int
	}{
		{"空链表", []int{}, []int{}},
		{"单个节点", []int{1}, []int{1}},
		{"两个节点", []int{1, 2}, []int{2, 1}},
		{"多个节点", []int{1, 2, 3, 4, 5}, []int{5, 4, 3, 2, 1}},
		{"偶数个节点", []int{1, 2, 3, 4}, []int{4, 3, 2, 1}},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			head := buildList(tt.input)
			reversed := ReverseListWithHash(head)
			got := listToSlice(reversed)

			if len(got) != len(tt.expected) {
				t.Fatalf("长度不匹配: got %d, want %d", len(got), len(tt.expected))
			}
			for i, v := range tt.expected {
				if got[i] != v {
					t.Errorf("索引 %d: got %d, want %d", i, got[i], v)
				}
			}
		})
	}
}

// ---------- 主函数（演示） ----------
func main() {
	// 演示
	head := buildList([]int{1, 2, 3, 4, 5})
	fmt.Println("原始链表:", listToSlice(head))
	reversed := ReverseListWithHash(head)
	fmt.Println("反转后:", listToSlice(reversed))
}
```

### 运行方式

- **直接运行演示**：

```bash
go run reverse_linked_list.go
```

- **执行单元测试**：

```bash
go test -v reverse_linked_list.go
```

