```cpp
#include <iostream>
#include <string>
#include <vector>

class UnionFind {
    std::vector<int> parent;

public:
    UnionFind(int n) : parent(n) {
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void unionSets(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            parent[rootY] = rootX;
        }
    }
};

std::string longestPalindrome(const std::string& s) {
    int n = s.size();
    UnionFind uf(n);
    for (int i = 0; i < n; i++) {
        uf.unionSets(i, i + 1);
        if (i < n - 1 && s[i] == s[i + 1]) {
            uf.unionSets(i, i + 2);
        }
    }
    std::vector<std::pair<int, int>> roots;
    for (int i = 0; i < n; i++) {
        if (i == 0 || s[i - 1] != s[i]) {
            roots.emplace_back(uf.find(i), i);
        }
    }
    std::string result;
    for (const auto& root : roots) {
        int start = root.second - root.first + 1;
        int len = (start / 2) * 2 + (start % 2);
        if (len > result.size()) {
            result = s.substr(root.second - len / 2, len);
        }
    }
    return result;
}

int main() {
    std::string s = "babad";
    std::cout << "Longest palindrome substring: " << longestPalindrome(s) << std::endl;
    return 0;
}
