#include <queue>

struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* reverseList(ListNode* head) {
    std::queue<ListNode*> q;
    ListNode* curr = head;
    while (curr != nullptr) {
        q.push(curr);
        curr = curr->next;
    }

    ListNode* newHead = nullptr;
    while (!q.empty()) {
        ListNode* node = q.front();
        q.pop();
        node->next = newHead;
        newHead = node;
    }

    return newHead;
}
