class Solution {
public:
    std::vector<int> mergeTwoLists(std::vector<int>& l1, std::vector<int>& l2) {
        std::priority_queue<int, std::vector<int>, std::greater<int>> pq;
        for (int num : l1) {
            pq.push(num);
        }
        for (int num : l2) {
            pq.push(num);
        }
        std::vector<int> result;
        while (!pq.empty()) {
            result.push_back(pq.top());
            pq.pop();
