    Val int
    Left *TreeNode
    Right *TreeNode
}

func levelOrderBottom(root *TreeNode) [][]int {
    if root == nil {
        return [][]int{}
    }

    // 使用哈希表存储层序遍历结果
    hash := make(map[int][]int)

    // 使用队列进行层序遍历
    queue := []*TreeNode{root}
    level := 0

    for len(queue) > 0 {
        size := len(queue)
        for i := 0; i < size; i++ {
            node := queue[0]
            queue = queue[1:]

            // 将节点添加到对应层级的哈希表中
            if _, ok := hash[level]; !ok {
                hash[level] = []int{node.Val}
            } else {
                hash[level] = append(hash[level], node.Val)
            }

            // 将子节点添加到队列中
            if node.Left != nil {
                queue = append(queue, node.Left)
            }
            if node.Right != nil {
                queue = append(queue, node.Right)
            }
        }
        level++
    }

    // 将哈希表转换为切片并排序
    res := make([][]int, len(hash))
    i := 0
    for k := range hash {
        res[i] = hash[k]
        i++
    }
    sort.Slice(res, func(i, j int) bool {
        return len(res[i]) > len(res[j])
    })

    return res
}
```

